if ~exist('src400s','var')
    src400s = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align_sym3.sqw');
end
file = src400s.full_filename %[output:1f687bea]
[~,fname] = fileparts(file);
w2_00 = cut(src400s,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);lz 0 1;liny; keep_figure; %[output:2fcfe65f]


% recover masks not to draw them again
[cuts2fit400HN,mask_file]  = recover_selected_cuts('cuts2fit400HN','e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits');
% retrieve selected cuts used for further fitting
[HN_FFCutsFits,allJfitfile] = recover_selected_cuts('HN_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

Add_bins400HN = {[-0.1,0.1],[-0.1,0.1],[0,2,300]};
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;
%%

% direction <110> offset 0.5,1.5,0; Max FF change

%w2_400a1 = cut(src400s,line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]),[0.04],[-0.1,0.1],[-0.1,0.1],[0,5,500]);
%plot(w2_400a1);liny; lz 0 1;keep_figure;
%w2_400a2 = cut(src400s,line_proj([1,1,0],[-1,1,0],'offset',[1.5,0.5,0]),[0.04],[-0.1,0.1],[-0.1,0.1],[0,5,500]);
%plot(w2_400a2); lz 0 1;keep_figure;

lp110ofH1H50 = line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]);
w2_400dir110ofH1H50 = cut(src400s,lp110ofH1H50,0.02,Add_bins400HN{:}, ...
    SymopReflection('norm',[-1,1,0],'offset',[1,1,0]));
plot(w2_400dir110ofH1H50);liny; lz 0 0.3;keep_figure; %[output:8b373b2e]
%%
w2_400dir110ofH1H50fit = cut(w2_400dir110ofH1H50,[-0.5,0.02,0.5],[100,2,230]); %[output:7b6d9e85]
plot(w2_400dir110ofH1H50fit);liny; lz 0 0.3;keep_figure; %[output:177a4d57]
HN_FFCutsFits = save_selected_cuts(HN_FFCutsFits,allJfitfile, ...
    'Ei400_offH1H0HNmaxFF',w2_400dir110ofH1H50fit);
%
%%
% direction <-110> offset 1.5,1.5,0; Min FF change; first and second BZ

lpM110off1H1H0 = line_proj([-1,1,0],[1,1,0],'offset',[1.5,1.5,0]);
w2e400dirM110of1H1H0 = cut(src400s,lpM110off1H1H0,[-1.5,0.02,1.5],Add_bins400HN{:});

fh = plot(w2e400dirM110of1H1H0); liny; lz 0 1; %[output:8539421d]
[w2e400dirM110of1H1H0,cuts2fit400HN] = draw_masks_helper(fh, ... %[output:8539421d]
    cuts2fit400HN,'msk1H1H0_dirM110',1); %[output:8539421d]
plot(w2e400dirM110of1H1H0); lz 0 0.3; keep_figure; %[output:8539421d]
%%
% symmeterize all around <1.5,1.5,0> point
w2_400HNoff1H1H0minFF = cut(w2e400dirM110of1H1H0,[0,0.01,0.5],[], ...
    SymopReflection('normvec',[-1,1,0],'offset',[1.5,1.5,0]));
plot(w2_400HNoff1H1H0minFF); lz 0 0.3; keep_figure; %[output:53f8c86f]
%
% symmeterize all around <0.5,2.5,0> point
w2_400HNoffH2H0minFF = cut(w2e400dirM110of1H1H0,[0,0.02,1.5],[], ...
    SymopReflection('normvec',[-1,1,0],'offset',[1.5,1.5,0]));
lpM110offH2H0 = line_proj([-1,1,0],[1,1,0],'offset',[.5,2.5,0]);
w2_400HNoffH2H0minFF = cut(w2_400HNoffH2H0minFF,lpM110offH2H0,[0,0.01,0.5],Add_bins400HN{1:2},[], ...
    SymopReflection('normvec',[-1,1,0],'offset',[0.5,2.5,0]));
plot(w2_400HNoffH2H0minFF); lz 0 0.3; keep_figure; %[output:8e98c2f8]

%%
HN_FFCutsFits = save_selected_cuts(HN_FFCutsFits,allJfitfile, ...
    'Ei400_off1H1H0HNminFF',cut(w2_400HNoff1H1H0minFF,[],[100,2,235]));
HN_FFCutsFits = save_selected_cuts(HN_FFCutsFits,allJfitfile, ...
    'Ei400_offH2H0HNminFF',cut(w2_400HNoffH2H0minFF,[],[100,2,270]));


save(mask_file,'cuts2fit400HN');
%%


